function getProfileByName(name) {
  return PROFILE_DATA[name] || null;
}

function instagramUrl(handle) {
  if (!handle) return "";
  return `https://www.instagram.com/${encodeURIComponent(handle.replace(/^@/, ""))}/`;
}
